const body = $input.first().json.body || $input.first().json;
const appId = body.applicationId || 'AICTE-2026-9024';
const action = body.reviewAction || 'RAISE_DEFICIENCY';
const notes = body.reviewNotes || 'Expired Fire Safety NOC. Valid certificate mandatory.';
const prevStage = body.previousStage || 'Scrutiny In Progress';
const now = new Date();
let nextStage = prevStage;
let nextStatus = 'Stage Updated';
let correctionDeadline = null;

if (action === 'APPROVE_STAGE') {
  nextStage = 'Pending EVC';
  nextStatus = 'Scrutiny Cleared - Ready for EVC Schedule';
} else if (action === 'RAISE_DEFICIENCY') {
  nextStage = 'Deficiency Raised';
  nextStatus = 'Awaiting College Correction: ' + notes;
  correctionDeadline = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000).toISOString();
}

return [{
  json: {
    applicationId: appId,
    reviewAction: action,
    previousStage: prevStage,
    newStage: nextStage,
    newStatus: nextStatus,
    correctionDeadline: correctionDeadline,
    reviewNotes: notes,
    fromEmail: 'salemranjan@gmail.com',
    toEmail: 'rolexleo345678@gmail.com',
    emailSubject: 'URGENT AICTE Notice: Document Deficiency & 7-Day Rectification [App: ' + appId + ']',
    emailHtml: '<div style="font-family: Arial, sans-serif; padding: 20px;"><div style="background-color: #0f2c59; padding: 15px; color: white; border-radius: 6px;"><h3 style="margin: 0;">ALL INDIA COUNCIL FOR TECHNICAL EDUCATION (AICTE)</h3><p style="margin: 3px 0 0 0; font-size: 12px; color: #f59e0b;">Scrutiny Bureau &bull; Ministry of Education</p></div><div style="padding: 15px; border: 1px solid #e2e8f0; border-top: none;"><p>Dear College Administrator,</p><p>During scrutiny of application <strong>' + appId + '</strong>, the following mandatory document deficiency was flagged:</p><div style="background: #fff1f2; border-left: 4px solid #e11d48; padding: 10px;"><strong style="color: #9f1239;">' + notes + '</strong></div><p>Statutory 7-day correction deadline: <strong>' + (correctionDeadline ? correctionDeadline.split('T')[0] : '7 days') + '</strong>.</p><p>Please upload the rectified document to the AICTE portal before the deadline to prevent Tier-2 Bureau Escalation.</p></div></div>',
    timestamp: now.toISOString()
  }
}];
